def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    population_size = 50
    population = rng.uniform(lb, ub, (population_size, dim))
    best_candidate = np.zeros(dim)
    best_fitness = float('inf')

    for _ in range(budget):
        fitness_values = [func(clip(c)) for c in population]
        min_index = np.argmin(fitness_values)
        if fitness_values[min_index] < best_fitness:
            best_fitness = fitness_values[min_index]
            best_candidate = population[min_index]

        offspring = []
        for i in range(population_size):
            p1, p2, p3 = rng.choice(population_size, 3, replace=False), \
                         rng.choice(population_size, 3, replace=False), \
                         rng.choice(population_size, 3, replace=False)
            if p1 != min_index and p2 != min_index and p3 != min_index:
                mutant = clip(best_candidate + rng.uniform(-1, 1) * (population[p1] - population[p2]) + rng.uniform(-1, 1) * (population[p3] - population[p2]))
                offspring.append(mutant)
        population = np.array(offspring)

    return best_candidate

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, a_min=lb, a_max=ub)

    pop_size = max(10 * dim**2 // (dim + 1), 4)
    mu = 1 / pop_size
    sigma = (ub - lb) / (3 * rng.randn() + 1.0)
    while budget > 0:
        budget -= pop_size
        x = rng.normal(loc=mu, scale=sigma, size=(pop_size, dim))
        x = clip(x)
        y = func(x)
        best_idx = np.argmin(y)
        if y[best_idx] < mu**2 * pop_size:
            sigma *= 0.5 ** (1 / (dim + 3))
            mu += rng.normal(loc=mu, scale=sigma, size=dim) * (ub - lb) / 2
            budget += pop_size
        else:
            x[best_idx] = clip(mu + rng.normal(loc=0, scale=sigma, size=dim))
            y[best_idx] = func(x[best_idx])
    return np.argmin(func(clip(rng.normal(loc=mu, scale=sigma, size=(1, dim)))))

